import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
const _p=Color(0xFF3E007D),_o=Color(0xFFFFA015);
class ErpHrStructureScreen extends StatefulWidget{const ErpHrStructureScreen({super.key,this.initialCompanyId,this.initialTab});final String? initialCompanyId;final String? initialTab;@override State<ErpHrStructureScreen> createState()=>_ErpHrStructureScreenState();}
class _ErpHrStructureScreenState extends State<ErpHrStructureScreen> with SingleTickerProviderStateMixin{
 late final TabController _tabs;final _code=TextEditingController(),_ar=TextEditingController(),_en=TextEditingController();List<Map<String,dynamic>> _deps=[],_jobs=[],_locs=[];String? _error;bool _loading=false;
 SupabaseClient? get _db{try{return Supabase.instance.client;}catch(_){return null;}}String get _cid=>(widget.initialCompanyId??'').trim();
 @override void initState(){super.initState();_tabs=TabController(length:3,vsync:this,initialIndex:widget.initialTab=='مواقع العمل'?2:widget.initialTab=='الوظائف والدرجات'?1:0);_load();}
 @override void dispose(){_tabs.dispose();_code.dispose();_ar.dispose();_en.dispose();super.dispose();}
 Future<void> _load()async{if(_cid.isEmpty||_db==null){setState(()=>_error='لا توجد شركة محددة.');return;}setState(()=>_loading=true);try{final x=await Future.wait([_db!.from('erp_hr_departments').select().eq('company_id',_cid).order('department_code'),_db!.from('erp_hr_jobs').select().eq('company_id',_cid).order('job_code'),_db!.from('erp_hr_work_locations').select().eq('company_id',_cid).order('location_code')]);if(mounted)setState(()=>{_deps=List<Map<String,dynamic>>.from(x[0]),_jobs=List<Map<String,dynamic>>.from(x[1]),_locs=List<Map<String,dynamic>>.from(x[2]),_loading=false,_error=null;});}catch(e){if(mounted)setState(()=>{_loading=false;_error='تعذر تحميل الهيكل. طبّق ترحيل الموارد البشرية أولًا: '+e.toString();});}}
 Future<void> _add(String kind)async{_code.clear();_ar.clear();_en.clear();final loc=kind=='loc',job=kind=='job';final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(loc?'إضافة موقع عمل':job?'إضافة وظيفة':'إضافة إدارة أو قسم'),content:SizedBox(width:420,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:_code,decoration:const InputDecoration(labelText:'الكود (حروف إنجليزية ثم أرقام)')),TextField(controller:_ar,decoration:const InputDecoration(labelText:'الاسم بالعربية')),TextField(controller:_en,decoration:const InputDecoration(labelText:'الاسم بالإنجليزية'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))]));if(ok!=true||_code.text.trim().isEmpty||_ar.text.trim().isEmpty)return;try{if(loc){await _db!.from('erp_hr_work_locations').insert({'company_id':_cid,'location_code':_code.text.trim().toUpperCase(),'name_ar':_ar.text.trim(),'location_type':_code.text.toUpperCase().contains('CENT')?'central':'branch'});}else if(job){await _db!.from('erp_hr_jobs').insert({'company_id':_cid,'job_code':_code.text.trim().toUpperCase(),'name_ar':_ar.text.trim(),'name_en':_en.text.trim()});}else{await _db!.from('erp_hr_departments').insert({'company_id':_cid,'department_code':_code.text.trim().toUpperCase(),'name_ar':_ar.text.trim(),'name_en':_en.text.trim()});}await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر الحفظ: '+e.toString())));}}
 Widget _list(String title,List<Map<String,dynamic>> rows,String ck,String nk,String kind){return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Expanded(child:Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900,color:_p))),FilledButton.icon(onPressed:()=>_add(kind),icon:const Icon(Icons.add),label:const Text('إضافة'))]),if(_loading)const LinearProgressIndicator(),Expanded(child:ListView(children:rows.map((r)=>Card(child:ExpansionTile(leading:Icon(kind=='loc'?Icons.location_on_outlined:Icons.account_tree_outlined,color:_o),title:Text(r[ck].toString()+' • '+r[nk].toString(),style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(r['is_active']==false?'غير نشط':'نشط'),children:_deps.where((d)=>d['parent_id']==r['id']).map((d)=>ListTile(leading:const Icon(Icons.subdirectory_arrow_left,color:_p),title:Text(d['department_code'].toString()+' • '+d['name_ar'].toString()),subtitle:Text(_jobs.where((j)=>j['department_id']==d['id']).map((j)=>j['job_code'].toString()+' • '+j['name_ar'].toString()).join(' | ')))).toList())).toList()))]);}
 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Align(alignment:Alignment.centerRight,child:Text('الهيكل التنظيمي والوظائف ومواقع العمل',style:TextStyle(fontSize:23,fontWeight:FontWeight.w900,color:_p))),if(_error!=null)Text(_error!,style:const TextStyle(color:Colors.red)),TabBar(controller:_tabs,labelColor:_p,indicatorColor:_o,tabs:const [Tab(text:'الإدارات والأقسام'),Tab(text:'الوظائف والدرجات'),Tab(text:'مواقع العمل')]),Expanded(child:TabBarView(controller:_tabs,children:[_list('شجرة الإدارات والأقسام',_deps.where((d)=>d['parent_id']==null).toList(),'department_code','name_ar','dept'),_list('دليل الوظائف',_jobs,'job_code','name_ar','job'),_list('مواقع العمل',_locs,'location_code','name_ar','loc')]))])));
}
